#!/usr/bin/env python3
"""Build IR22 for the two original C12 batch-16 medium readings."""
import hashlib,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parent
PACKAGE_ID='IR-20261124-22'; SOURCE_COMMIT='db49f7e09163fc5aad7d4b88bb88582bb62804a6'; SOURCE_PATH='completion/c12-batch16/drafts.json'; CASE_IDS=['m-c12-20261124-26','m-c12-20261124-27']
def canonical(v): return json.dumps(v,ensure_ascii=False,sort_keys=True).encode()
rows={x['id']:x for x in json.loads(subprocess.check_output(['git','show',f'{SOURCE_COMMIT}:{SOURCE_PATH}']))}; assert set(rows)==set(CASE_IDS)
cases=[{'case_id':cid,'kind':'reading','sources':[{'commit':SOURCE_COMMIT,'path':SOURCE_PATH}],'fields':rows[cid]} for cid in CASE_IDS]; sources_sha256=hashlib.sha256(canonical(cases)).hexdigest()
instructions=('Проведи незалежний мовний аудит вкладених матеріалів. Працюй лише з цим пакетом і фактично перевіреними словниковими джерелами. Не читай авторські звіти чи історію чату. Не припускай, що кожен матеріал містить помилку. Альтернативний коректний переклад сам по собі не є помилкою.\nПеревір природність і зв’язність японського тексту, точність і природність українського перекладу та внутрішню узгодженість. Для кожного питання перевір усі варіанти, єдиність ключа, природність і правдоподібність distractors, підказки довжиною, граматичною формою чи логікою без знання тексту, точність пояснення й evidence.\nЗафіксуй кожне перевірене й пропущене поле. Не видавай структурні тести за мовну перевірку, не вигадуй джерела, невпевненість позначай. Поверни один JSON за return_template; верхнє поле в checked_fields дозволене лише після повної перевірки. Для зауважень наведи evidence і proposed_change. Збережи package_id та sources_sha256.')
scope={'vocab_ids':[],'meaning_contexts':0,'readings':2,'reading_questions':4}
package={'schema_version':1,'package_id':PACKAGE_ID,'instructions':instructions,'sources_sha256':sources_sha256,'scope':scope,'cases':cases,'return_template':{'schema_version':1,'package_id':PACKAGE_ID,'sources_sha256':sources_sha256,'reviewer':{'system':'ChatGPT','session':'','reviewed_at':'','participated_in_authoring':False},'cases':[{'case_id':cid,'checked_fields':[],'unchecked_fields':['id','title','ja','uk','contextNotes','questions'],'verdict':'not_reviewed','findings':[]} for cid in CASE_IDS],'finding_format':{'field_path':'','severity':'minor|major|critical','confidence':'high|medium|low','claim':'','evidence':'','sources':[],'proposed_change':''},'allowed_verdicts':['pass','issues','uncertain','not_reviewed']}}
path=ROOT/f'packages/{PACKAGE_ID}.json'; path.write_text(json.dumps(package,ensure_ascii=False,indent=2)+'\n'); package_sha256=hashlib.sha256(path.read_bytes()).hexdigest()
qp=ROOT/'queue.json'; queue=json.loads(qp.read_text()); assert not any(x['package_id']==PACKAGE_ID for x in queue['packages']); queue['packages'].append({'package_id':PACKAGE_ID,'path':f'packages/{PACKAGE_ID}.json','package_sha256':package_sha256,'sources_sha256':sources_sha256,'source_commits':[SOURCE_COMMIT],'status':'pending_review','predecessor':None,'scope':scope,'reviews':[],'history':[{'status':'pending_review','date':'2026-11-24'}],'notes':'Two original C12 batch-16 medium readings and four questions from released v229-C12q.'}); qp.write_text(json.dumps(queue,ensure_ascii=False,indent=2)+'\n')
mp=ROOT/'QUEUE.md'; md=mp.read_text(); marker='| [IR-20261123-21]'; line='| [IR-20261124-22](packages/IR-20261124-22.json) | pending_review | 0 карток, 2 тексти, 4 питання | Очікується |\n'; pos=md.index('\n',md.index(marker))+1
md=md[:pos]+line+md[pos:]+('\n## IR-20261124-22\n\nДва оригінальні середні тексти C12 із випуску v229-C12q та чотири питання. Авторські оцінки в пакет не включено. Джерело — release commit `db49f7e09163fc5aad7d4b88bb88582bb62804a6`; Chromium 45207734307, branch data-check 45207732858 і main data-check 45208704672 успішні.\n'); mp.write_text(md)
print(json.dumps({'package_id':PACKAGE_ID,'package_sha256':package_sha256,'sources_sha256':sources_sha256}))
